WITH exploded AS (SELECT id, service, log_ts, level, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS key, v), parsed AS (SELECT log_ts, CAST((status_code & 8) != 0 AS INT) AS has_fault, SHIFTRIGHT(status_code, 2) AS status_code_high FROM exploded WHERE log_ts < '2024-04-01'), with_windows AS (SELECT has_fault, status_code_high, COUNT(has_fault) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS has_fault_count_1h FROM parsed), valid AS (SELECT *, status_code_high * has_fault AS status_code_high_times_has_fault FROM with_windows WHERE has_fault > 1), metrics AS (SELECT *, CUME_DIST() OVER (ORDER BY has_fault_count_1h DESC NULLS FIRST) AS has_fault_count_1h_cume_dist, PERCENT_RANK() OVER (ORDER BY status_code_high_times_has_fault) AS status_code_high_times_has_fault_percent_rank, DENSE_RANK() OVER (ORDER BY status_code_high_times_has_fault NULLS LAST) AS status_code_high_times_has_fault_dense_rank FROM valid WHERE has_fault_count_1h BETWEEN 6 AND 12), enriched AS (SELECT has_fault, has_fault_count_1h_cume_dist, status_code_high_times_has_fault_percent_rank, status_code_high_times_has_fault_dense_rank, RANK() OVER (ORDER BY has_fault_count_1h DESC NULLS LAST) AS has_fault_count_1h_rank, DENSE_RANK() OVER (ORDER BY status_code_high_times_has_fault_dense_rank DESC) AS status_code_high_times_has_fault_dense_rank_dense_rank, RANK() OVER (ORDER BY has_fault DESC NULLS LAST) AS has_fault_rank FROM metrics), filtered AS (SELECT has_fault_count_1h_cume_dist, status_code_high_times_has_fault_percent_rank, status_code_high_times_has_fault_dense_rank, has_fault_count_1h_rank, ROUND(has_fault_rank, 2) AS has_fault_rank_rounded FROM enriched WHERE has_fault > 0) SELECT CASE WHEN status_code_high_times_has_fault_dense_rank >= 9 THEN 'HIGH' ELSE 'LOW' END AS status_code_high_times_has_fault_dense_rank_tier, ROUND(AVG(status_code_high_times_has_fault_dense_rank), 2) AS avg_status_code_high_times_has_fault_dense_rank, APPROX_PERCENTILE(status_code_high_times_has_fault_percent_rank, 0.5) AS status_code_high_times_has_fault_percent_rank_p50 FROM filtered GROUP BY CASE WHEN status_code_high_times_has_fault_dense_rank >= 9 THEN 'HIGH' ELSE 'LOW' END HAVING ROUND(AVG(status_code_high_times_has_fault_dense_rank), 2) > 0
